// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 value, uint64 warpTime, uint64 blockNum) public {
        // Restrict to admissible domain where the fallback can be successfully entered
        vm.assume(warpTime > 0);
        vm.assume(value > 0);
        vm.assume(blockNum > 0);

        // set block timestamp and block number
        vm.warp(warpTime);
        vm.roll(blockNum);

        // fund caller with enough Ether for either 10 or 1 ether
        address caller = address(0xbad);
        vm.deal(caller, 100 ether);

        bool reverted;
        vm.prank(caller);
        try c.fallback{value: value}() {
            reverted = false;
        } catch {
            reverted = true;
        }

        // General rule: if a call succeeds, the contract's balance never decreases.
        // The reference returns true because it only proceeds when value == 10 ether,
        // and even then transfer only happens on blockNum % 15 == 0; but the ensure
        // lock (pastBlockTime) prevents a second call in the same block, so the Ether
        // never actually moves out because block timestamp is strictly increasing.
        // Buggy version: a 1-ether call can succeed and, when block.number % 15 == 0,
        // send the entire balance to the caller, breaking the no-balance-decrease invariant.
        uint256 balanceAfter = address(c).balance;
        bool invariantHolds = reverted || balanceAfter >= 10 ether - value; // original always ends with ≥10 - value? Not exact.
        // For reference, balance stays >= value sent (minus possible re-entry not applicable).
        // Actually produce a bulletproof invariant:
        // Reference: after any successful non-reverted call, c's balance equals at least its previous balance.
        // We simulate by running two fuzzed calls in sequence to expose transfer?
        // Simplify: assert that balance after any call is at least the original balance (10 ether from constructor).
        // Since constructor has payable, c initially has 0. So skip.
        // Over a single arbitrary call, reference only ever increases balance (except impossible transfer).
        // Invariant: address(c).balance >= value (money sent) when call succeeds, but better: c balance never < previous balance.
        // So we need before snapshot; simulate with a fresh contract per fuzz.
        // The invariant: after any non-reverted call, balance == value added. Because transfer unreachable in reference.
        // Bug: transfer drains excess.
        // Concrete invariant: c's balance after a successful call is at least the value sent to it.
        assertTrue(reverted || address(c).balance >= value);
    }
}

