pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 seedBalance, uint256 roll) public {
        // Bound the roll to a block number that triggers the transfer branch
        roll = bound(roll, 1, type(uint64).max);
        vm.assume(roll % 15 == 0);
        // Bound the seed balance so that we can pre-fund the contract with at least 10 ether
        seedBalance = bound(seedBalance, 10 ether, type(uint128).max);
        // Fund the contract by sending two fallback calls: one to set a balance, one to trigger the transfer
        uint256 time = 1;
        vm.warp(time);
        vm.roll(roll);
        vm.deal(address(this), seedBalance + 10 ether);
        // First call: seed the contract balance with seedBalance
        vm.prank(address(this));
        (bool ok1,) = address(c).call{value: seedBalance}("");
        require(ok1, "first call failed");
        // Advance time to pass the timestamp check
        vm.warp(time + 1);
        // Second call: send exactly 10 ether; this should trigger the transfer because roll % 15 == 0
        vm.prank(address(this));
        (bool ok2,) = address(c).call{value: 10 ether}("");
        require(ok2, "second call failed");
        // Assert: after the second fallback (which hit the transfer branch), the contract balance must be zero.
        assertEq(address(c).balance, 0);
    }
}

