pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 senderKey, uint8 offset) public {
        // Use senderKey to generate a deterministic EOA; offset to vary block.number and block.timestamp
        address sender = vm.addr(senderKey % (2**160 - 1) + 1);
        vm.assume(sender != address(0) && sender != address(this));
        vm.assume(offset > 0);
        uint256 value = 10 ether;

        // Ensure block.number and block.timestamp are well-behaved
        vm.roll(block.number + offset);
        vm.warp(block.timestamp + offset + 1);

        vm.deal(sender, value);

        // First fallback call
        vm.prank(sender);
        c.fallback{value: value}();

        uint256 balanceAfterFirst = address(c).balance;
        bool firstDivisible = block.number % 15 == 0;

        // Advance state for second call (must satisfy require(block.timestamp > pastBlockTime))
        vm.roll(block.number + 1);
        vm.warp(block.timestamp + 2);
        vm.deal(sender, value);

        // Second fallback call
        vm.prank(sender);
        c.fallback{value: value}();

        uint256 balanceAfterSecond = address(c).balance;
        bool secondDivisible = block.number % 15 == 0;

        // After the second call, if the second call's block.number % 15 == 0, the reference transfers the entire balance (0 left),
        // but the bug transfers only 1 ether, leaving balanceAfterFirst + value - 1 ether.
        // If the second call's block.number % 15 != 0, both just accumulate value.
        // The general rule: after the second call, if secondDivisible is true, the reference balance is 0,
        // but this is too strong as a universal invariant (it depends on the specific input).
        // We need a rule that holds for EVERY input.

        // Instead: the reference always satisfies that the balance is either 0 (if last call triggered transfer) or equal to the accumulated value.
        // But we can assert a relational invariant: the contract's balance after two calls must be equal to the sum of values sent minus any full-balance transfers.
        // However, the fuzzer supplies senderKey and offset, so block.number % 15 is variable.

        // Correct invariant: after any sequence of successful fallback calls, the balance is equal to the total value sent minus sum of balances transferred when block.number % 15 == 0.
        // For the reference, when block.number % 15 == 0, the entire current balance is transferred, so the remaining balance is 0.
        // For the bug, only 1 ether is transferred, leaving the rest.
        // The invariant: if the last call's block.number % 15 == 0, then address(c).balance must be 0 for the reference.
        // This is a conditional property: for a given call that ends with block.number % 15 == 0, the balance after is 0.
        // We can assert: after any fallback call where block.number % 15 == 0, address(c).balance == 0.
        // In the reference, this is true because the fallback transfers the entire balance.
        // In the bug, if there was a prior balance, the transfer of only 1 ether leaves a non-zero remainder.
        // Since we call fallback twice, the second call with block.number % 15 == 0 will break the bug.
        // But we can't control block.number % 15; we can use offset to make it hit or miss.
        // The fuzzer will find an offset where block.number % 15 == 0, and the assertion fails for the bug.

        // However, we need a property that holds for ALL inputs (every offset).
        // The conditional property "if block.number % 15 == 0, then balance == 0" holds for ALL offsets in the reference.
        // We'll assert exactly that.

        if (secondDivisible) {
            assertEq(balanceAfterSecond, 0);
        }
        // Note: For the reference, this assertion passes for all offsets where secondDivisible is true.
        // For the bug, when secondDivisible is true and there was a prior balance (balanceAfterFirst > 0),
        // balanceAfterSecond will be balanceAfterFirst + value - 1 ether != 0, so assertion fails.
    }
}

